// Dev-only mock OpenAI-compatible server for testing the explain flow
// without a real API key. Run: pnpm mock-ai
// It speaks SSE streaming and replies in the language of the system prompt
// (English or Arabic) so the full EN/AR pipeline can be exercised.
import http from "node:http";

const PORT = Number(process.env.PORT ?? 8765);

const EXPLANATION_EN =
  "This is a mock explanation generated by the local test server. " +
  "1) What the paper is about: it presents a new approach in its field. " +
  "2) How it works: the authors combine existing methods with a novel idea. " +
  "3) Key results: the approach improves over baselines on standard benchmarks. " +
  "4) Why it matters: it opens the door for more efficient and accessible research. " +
  "Remember to configure a real provider (OpenAI, OpenRouter, DeepSeek, Ollama…) in Settings.";

const EXPLANATION_AR =
  "هذا شرح تجريبي من خادم الاختبار المحلي. " +
  "١) ما موضوع الورقة: تقدّم منهجًا جديدًا في مجالها. " +
  "٢) كيف تعمل: يجمع المؤلفون بين طرق قائمة وفكرة مبتكرة. " +
  "٣) النتائج الرئيسية: يتفوق المنهج على الأساليب المعيارية في المقاييس المعروفة. " +
  "٤) لماذا هي مهمة: تفتح الباب أمام أبحاث أكثر كفاءة وسهولة في الوصول. " +
  "تذكّر أن تضبط مزوّدًا حقيقيًا (OpenAI أو OpenRouter أو DeepSeek أو Ollama…) في الإعدادات.";

const CORS_HEADERS = {
  "access-control-allow-origin": "*",
  "access-control-allow-methods": "GET, POST, OPTIONS",
  "access-control-allow-headers": "Content-Type, Authorization",
  "access-control-max-age": "600",
};

const server = http.createServer((req, res) => {
  let body = "";
  req.on("data", (chunk) => (body += chunk));
  req.on("end", () => {
    const url = new URL(req.url ?? "/", `http://${req.headers.host}`);

    // CORS preflight (browser clients).
    if (req.method === "OPTIONS") {
      res.writeHead(204, CORS_HEADERS);
      res.end();
      return;
    }

    if (req.method === "GET" && url.pathname === "/v1/models") {
      res.writeHead(200, { "content-type": "application/json", ...CORS_HEADERS });
      res.end(JSON.stringify({ data: [{ id: "mock-model" }] }));
      return;
    }

    if (req.method === "POST" && url.pathname.endsWith("/chat/completions")) {
      let parsed = {};
      try {
        parsed = JSON.parse(body);
      } catch {
        /* malformed body — respond anyway */
      }
      const messages = Array.isArray(parsed.messages) ? parsed.messages : [];
      const systemPrompt = messages.find((m) => m.role === "system")?.content ?? "";
      const arabic = systemPrompt.includes("اللغة العربية");
      const text = arabic ? EXPLANATION_AR : EXPLANATION_EN;
      const stream = parsed.stream !== false;

      if (!stream) {
        res.writeHead(200, { "content-type": "application/json", ...CORS_HEADERS });
        res.end(
          JSON.stringify({ choices: [{ message: { role: "assistant", content: text } }] }),
        );
        return;
      }

      res.writeHead(200, {
        "content-type": "text/event-stream",
        "cache-control": "no-cache",
        connection: "keep-alive",
        ...CORS_HEADERS,
      });

      const words = text.split(" ");
      let i = 0;
      const timer = setInterval(() => {
        if (i >= words.length) {
          res.write("data: [DONE]\n\n");
          res.end();
          clearInterval(timer);
          return;
        }
        const payload = JSON.stringify({
          choices: [{ delta: { content: words[i] + " " } }],
        });
        res.write(`data: ${payload}\n\n`);
        i += 1;
      }, 35);
      return;
    }

    res.writeHead(404, { "content-type": "text/plain" });
    res.end("not found");
  });
});

server.listen(PORT, () => {
  console.log(`Mock AI server listening on http://localhost:${PORT}/v1`);
  console.log("Configure it in Papyrus Settings as a provider:");
  console.log(`  Base URL: http://localhost:${PORT}/v1`);
  console.log("  Model:    mock-model");
  console.log("  API key:  anything (or empty)");
});
